type Json = { [key: string]: unknown };

const BEGIN = /^<!-- generated:begin ([a-z0-9:_-]+) -->$/;
const END = '<!-- generated:end -->';

// ---------------------------------------------------------------------------
// Small helpers
// ---------------------------------------------------------------------------

function header(title: string, source: string, intro: string): string[] {
  return [
    `<!-- GENERATED FILE: do not edit. Run \`npm run docs:reference\`. Source: ${source} -->`,
    '',
    `# ${title}`,
    '',
    `> Generated from the code by \`scripts/generate-docs-reference.ts\`. Do not edit this file: change the code and run \`npm run docs:reference\`.`,
    '',
    intro,
    '',
  ];
}

/** Escapes what would break a table cell, and `<` outside code spans, which the site would read as an HTML tag. */
function escapeCell(text: string): string {
  const flat = text.replace(/\s*\n\s*/g, ' ').trim();
  return flat
    .split('`')
    .map((part, index) => (index % 2 === 0 ? part.replace(/</g, '&lt;') : part).replace(/\|/g, '\\|'))
    .join('`');
}

function code(text: string): string {
  return `\`${text}\``;
}

function table(head: string[], rows: string[][]): string[] {
  const lines = [`| ${head.join(' | ')} |`, `|${head.map(() => '---').join('|')}|`];
  for (const row of rows) lines.push(`| ${row.map(escapeCell).join(' | ')} |`);
  return lines;
}

function asObject(value: unknown): Json {
  return value !== null && typeof value === 'object' && !Array.isArray(value) ? (value as Json) : {};
}

function asArray(value: unknown): unknown[] {
  return Array.isArray(value) ? value : [];
}

function str(value: unknown): string | undefined {
  return typeof value === 'string' ? value : undefined;
}

// ---------------------------------------------------------------------------
// Doc comments of the constants (`/** ... */` above each key of an `as const` object)
// ---------------------------------------------------------------------------

interface ConstantDoc {
  key: string;
  value: string;
  doc: string;
}

/** Reads `export const Name = { /** doc *\/ Key: 'value', ... } as const;` blocks from a source file. */
function parseConstantDocs(source: string): Map<string, ConstantDoc[]> {
  const result = new Map<string, ConstantDoc[]>();
  const lines = source.split('\n');
  for (let i = 0; i < lines.length; i += 1) {
    const start = /^export const (\w+) = \{\s*$/.exec(lines[i] ?? '');
    if (!start) continue;
    const entries: ConstantDoc[] = [];
    let pending: string[] = [];
    let inComment = false;
    for (i += 1; i < lines.length; i += 1) {
      const line = (lines[i] ?? '').trim();
      if (/^\} as const;/.test(line)) break;
      if (inComment) {
        const closes = line.includes('*/');
        const text = line.replace(/\*\/.*$/, '').replace(/^\*\s?/, '').trim();
        if (text) pending.push(text);
        if (closes) inComment = false;
        continue;
      }
      if (line.startsWith('/**')) {
        const closes = line.includes('*/');
        const text = line.replace(/^\/\*\*\s?/, '').replace(/\s?\*\/.*$/, '').trim();
        pending = text ? [text] : [];
        inComment = !closes;
        continue;
      }
      const entry = /^(\w+):\s*'([^']*)',?/.exec(line);
      if (entry) {
        entries.push({ key: entry[1] as string, value: entry[2] as string, doc: pending.join(' ') });
        pending = [];
      }
    }
    result.set(start[1] as string, entries);
  }
  return result;
}

function readSource(relative: string): string {
  return readFileSync(join(ROOT, relative), 'utf8');
}

const CONSTANT_DOCS = new Map<string, ConstantDoc[]>([
  ...parseConstantDocs(readSource('src/constants.ts')),
  ...parseConstantDocs(readSource('src/scheduler/constants.ts')),
  ...parseConstantDocs(readSource('src/routing/constants.ts')),
  ...parseConstantDocs(readSource('src/purchase/constants.ts')),
]);

// ---------------------------------------------------------------------------
// JSON Schema rendering
// ---------------------------------------------------------------------------

interface Pages {
  /** Component name -> page file (relative to docs/reference/generated) that documents it. */
  where: Map<string, string>;
}

function anchor(name: string): string {
  return name.toLowerCase().replace(/[^a-z0-9]+/g, '-');
}

function refLink(name: string, from: string, pages: Pages): string {
  const page = pages.where.get(name);
  if (page === undefined) return code(name);
  const target = page === from ? `#${anchor(name)}` : `${page}#${anchor(name)}`;
  return `[${name}](${target})`;
}

function constraint(schema: Json): string[] {
  const parts: string[] = [];
  const num = (key: string): number | undefined => (typeof schema[key] === 'number' ? (schema[key] as number) : undefined);
  const minLength = num('minLength');
  const maxLength = num('maxLength');
  if (minLength !== undefined && maxLength !== undefined) parts.push(`${minLength} to ${maxLength} characters`);
  else if (minLength !== undefined) parts.push(minLength === 1 ? 'not empty' : `at least ${minLength} characters`);
  else if (maxLength !== undefined) parts.push(`at most ${maxLength} characters`);
  const minimum = num('minimum');
  const maximum = num('maximum');
  const exclusiveMinimum = num('exclusiveMinimum');
  if (minimum !== undefined && maximum !== undefined) parts.push(`${minimum} to ${maximum}`);
  else if (minimum !== undefined) parts.push(`at least ${minimum}`);
  else if (maximum !== undefined) parts.push(`at most ${maximum}`);
  if (exclusiveMinimum !== undefined) parts.push(`greater than ${exclusiveMinimum}`);
  const minItems = num('minItems');
  if (minItems !== undefined) parts.push(`at least ${minItems} item${minItems === 1 ? '' : 's'}`);
  const pattern = str(schema.pattern);
  if (pattern !== undefined && schema.format !== 'date-time') parts.push(`pattern ${code(pattern)}`);
  if (schema.default !== undefined) parts.push(`default ${code(JSON.stringify(schema.default))}`);
  return parts;
}

function typeOf(schema: Json, from: string, pages: Pages): string {
  const ref = str(schema.$ref);
  if (ref !== undefined) return refLink(ref.slice(ref.lastIndexOf('/') + 1), from, pages);
  const variants = asArray(schema.anyOf ?? schema.oneOf);
  if (variants.length > 0) {
    const unique = variants
      .map((variant) => typeOf(asObject(variant), from, pages))
      .filter((text, index, all) => all.indexOf(text) === index);
    return unique.join(' or ');
  }
  if ('const' in schema) return code(JSON.stringify(schema.const));
  const values = asArray(schema.enum);
  if (values.length > 0) return `one of ${values.map((value) => code(String(value))).join(', ')}`;
  const type = schema.type;
  if (type === 'array') {
    return `array of ${typeOf(asObject(schema.items), from, pages)}`;
  }
  if (type === 'object') {
    const extra = asObject(schema.additionalProperties);
    if (Object.keys(extra).length > 0) return `map of string to ${typeOf(extra, from, pages)}`;
    if (schema.additionalProperties === true || Object.keys(asObject(schema.properties)).length === 0) return 'object';
    return 'object';
  }
  const format = str(schema.format);
  const base = typeof type === 'string' ? type : Object.keys(schema).length === 0 ? 'any JSON value' : 'any';
  const extras = constraint(schema);
  const label = format !== undefined ? `${base} (${format})` : base;
  return extras.length > 0 ? `${label}; ${extras.join(', ')}` : label;
}

function describeSchema(name: string, schema: Json, from: string, pages: Pages): string[] {
  const lines: string[] = [`### ${name}`, ''];
  const description = str(schema.description);
  if (description) lines.push(description, '');
  const enumValues = asArray(schema.enum);
  const properties = asObject(schema.properties);
  const required = new Set(asArray(schema.required).map(String));
  if (enumValues.length > 0) {
    lines.push(`One of: ${enumValues.map((value) => code(String(value))).join(', ')}.`, '');
  } else if (Object.keys(properties).length > 0) {
    const rows = Object.entries(properties).map(([field, raw]) => {
      const property = asObject(raw);
      const inline = Object.keys(property).filter((key) => key !== 'description');
      const stripped: Json = {};
      for (const key of inline) stripped[key] = property[key];
      return [
        code(field),
        typeOf(stripped, from, pages),
        required.has(field) ? 'yes' : 'no',
        str(property.description) ?? '',
      ];
    });
    lines.push(...table(['Field', 'Type', 'Required', 'Description'], rows), '');
  } else if (asArray(schema.oneOf).length > 0 || asArray(schema.anyOf).length > 0) {
    lines.push(`Either ${typeOf(schema, from, pages)}.`, '');
    const discriminator = asObject(schema.discriminator);
    if (str(discriminator.propertyName)) {
      const mapping = Object.entries(asObject(discriminator.mapping)).map(([value, target]) => [
        code(value),
        refLink(String(target).slice(String(target).lastIndexOf('/') + 1), from, pages),
      ]);
      lines.push(`Switch on ${code(String(discriminator.propertyName))}:`, '', ...table(['Value', 'Model'], mapping), '');
    }
  } else {
    lines.push(`Type: ${typeOf(schema, from, pages)}.`, '');
  }
  return lines;
}

function isEnumSchema(schema: Json): boolean {
  return asArray(schema.enum).length > 0 && schema.type === 'string';
}

// ---------------------------------------------------------------------------
// Models, enums and scheduler records
// ---------------------------------------------------------------------------

const ENUMS_PAGE = 'enums.md';
const MODELS_PAGE = 'models.md';
const SCHEDULER_PAGE = 'scheduler-records.md';

/** Zod schemas of the scheduler that are not part of the OpenAPI document. */
const SCHEDULER_OUTPUTS = {
  ScheduleRecord: SchedulerSchemas.ScheduleRecordSchema,
  CycleRecord: SchedulerSchemas.CycleRecordSchema,
  AttemptRecord: SchedulerSchemas.AttemptRecordSchema,
  LastFailure: SchedulerSchemas.LastFailureSchema,
  CycleError: SchedulerSchemas.CycleErrorSchema,
  SchedulerEvent: SchedulerSchemas.SchedulerEventSchema,
  CycleStatus: SchedulerSchemas.CycleStatusSchema,
} as const;

const SCHEDULER_INPUTS = {
  SchedulePolicy: SchedulerSchemas.SchedulePolicySchema,
  SchedulerConfig: SchedulerSchemas.SchedulerConfigSchema,
  RegisterScheduleInput: SchedulerSchemas.RegisterScheduleInputSchema,
  ActivateScheduleInput: SchedulerSchemas.ActivateScheduleInputSchema,
  PauseScheduleInput: SchedulerSchemas.PauseScheduleInputSchema,
  ResumeScheduleInput: SchedulerSchemas.ResumeScheduleInputSchema,
  UpdateScheduleInput: SchedulerSchemas.UpdateScheduleInputSchema,
  CancelScheduleInput: SchedulerSchemas.CancelScheduleInputSchema,
  TickOptions: SchedulerSchemas.TickOptionsSchema,
  SchedulePauser: SchedulerSchemas.SchedulePauserSchema,
} as const;

function openApiSchemas(): Record<string, Json> {
  const document = buildOpenApiDocument({});
  return document.components.schemas as Record<string, Json>;
}

function schedulerSchemas(): Record<string, Json> {
  const output = exportJsonSchemas({ refPrefix: '#/components/schemas/', io: 'output', extra: SCHEDULER_OUTPUTS }).schemas;
  const input = exportJsonSchemas({ refPrefix: '#/components/schemas/', io: 'input', extra: SCHEDULER_INPUTS }).schemas;
  const result: Record<string, Json> = {};
  for (const name of Object.keys(SCHEDULER_OUTPUTS)) result[name] = output[name] as Json;
  for (const name of Object.keys(SCHEDULER_INPUTS)) result[name] = input[name] as Json;
  return result;
}

function buildPages(): { pages: Pages; models: Record<string, Json>; scheduler: Record<string, Json> } {
  const models = openApiSchemas();
  const scheduler = schedulerSchemas();
  const where = new Map<string, string>();
  for (const [name, schema] of Object.entries(models)) where.set(name, isEnumSchema(schema) ? ENUMS_PAGE : MODELS_PAGE);
  for (const [name, schema] of Object.entries(scheduler)) {
    where.set(name, isEnumSchema(schema) ? ENUMS_PAGE : SCHEDULER_PAGE);
  }
  return { pages: { where }, models, scheduler };
}

/** The constants object behind an enum schema, from the shared or the scheduler constants. */
function enumsPage(models: Record<string, Json>, scheduler: Record<string, Json>): string {
  const lines = header(
    'Enumerations',
    'src/constants.ts, src/scheduler/constants.ts',
    'Every string that carries meaning is an exported constant: use `SubscriptionStatus.Active`, never `\'active\'`. ' +
      'Each table lists the constant, the value that travels over the wire, and what it means.',
  );
  const all: [string, Json][] = [
    ...Object.entries(models).filter(([, schema]) => isEnumSchema(schema)),
    ...Object.entries(scheduler).filter(([, schema]) => isEnumSchema(schema)),
  ];
  const seen = new Set<string>();
  for (const [name, schema] of all) {
    if (seen.has(name)) continue;
    seen.add(name);
    lines.push(`### ${name}`, '');
    const description = str(schema.description);
    if (description) lines.push(description, '');
    const values = asArray(schema.enum).map(String);
    const documented = CONSTANT_DOCS.get(name);
    const rows = values.map((value) => {
      const entry = documented?.find((candidate) => candidate.value === value);
      return [entry ? code(`${name}.${entry.key}`) : '', code(value), entry?.doc ?? ''];
    });
    lines.push(...table(['Constant', 'Value', 'Meaning'], rows), '');
  }
  return lines.join('\n');
}

function modelsPage(models: Record<string, Json>, pages: Pages): string {
  const lines = header(
    'Models',
    'src/schemas.ts, src/server/routes.ts (via the OpenAPI document)',
    'Every model that crosses the API, as the HTTP service publishes it in its OpenAPI document. Amounts are integers in paise. ' +
      'Instants are ISO-8601 strings with an offset. Models used in a request are shown as a caller sends them (defaults optional); ' +
      'all others as a caller receives them. The same shapes are Zod schemas you can import from `india-subscriptions`.',
  );
  for (const [name, schema] of Object.entries(models)) {
    if (isEnumSchema(schema)) continue;
    lines.push(...describeSchema(name, schema, MODELS_PAGE, pages));
  }
  return lines.join('\n');
}

function schedulerPage(scheduler: Record<string, Json>, pages: Pages): string {
  const lines = header(
    'Scheduler records and options',
    'src/scheduler/schemas.ts',
    'What the billing scheduler stores and accepts. The records are plain JSON: a `SchedulerStore` keeps them unchanged. ' +
      'Inputs are shown as a caller passes them (defaults optional); records as the scheduler writes them.',
  );
  for (const [name, schema] of Object.entries(scheduler)) {
    if (isEnumSchema(schema)) continue;
    lines.push(...describeSchema(name, schema, SCHEDULER_PAGE, pages));
  }
  return lines.join('\n');
}

// ---------------------------------------------------------------------------
// HTTP API
// ---------------------------------------------------------------------------

const AUTH_LABEL: Record<AuthMode, string> = {
  [AuthMode.None]: 'none',
  [AuthMode.Bearer]: 'API key (`Authorization: Bearer ...`)',
  [AuthMode.Signature]: 'none: the gateway\'s signature over the raw body',
  [AuthMode.Capability]: 'none: the unguessable session id in the path',
};

function httpApiPage(pages: Pages): string {
  const document = buildOpenApiDocument({});
  const lines = header(
    'HTTP API',
    'src/server/routes.ts, src/server/openapi.ts',
    'Every route of the service started by `india-subscriptions serve` or `createHandler`. The table is read from the route table the ' +
      'request dispatcher itself uses, so it is the behaviour, not a description of it. The same information, machine-readable, is served at ' +
      '`GET /v1/openapi.json` and committed as `openapi/openapi.json`.',
  );
  lines.push(
    ...table(
      ['Operation', 'Method', 'Path', 'Auth'],
      routes.map((route) => [
        refRoute(route.operationId),
        route.method,
        code(route.path),
        AUTH_LABEL[route.auth],
      ]),
    ),
    '',
  );
  const tags = [...new Set(routes.map((route) => route.tag))];
  for (const tag of tags) {
    lines.push(`## ${tag}`, '');
    const description = document.tags.find((candidate) => candidate.name === tag)?.description;
    if (description) lines.push(description, '');
    for (const route of routes.filter((candidate) => candidate.tag === tag)) {
      const operation = asObject(asObject(document.paths[route.path])[route.method.toLowerCase()]);
      lines.push(`### ${route.operationId}`, '', `${code(`${route.method} ${route.path}`)}`, '', route.summary + '.', '', route.description, '');
      const rows: string[][] = [['Auth', AUTH_LABEL[route.auth]]];
      if (route.requestBody) {
        rows.push([
          'Request body',
          `${refLink(route.requestBody.schema, HTTP_PAGE, pages)}${route.requestBody.required ? '' : ' (optional)'}${route.requestBody.raw ? '; the raw body, exactly as the gateway sent it' : ''}`,
        ]);
      }
      for (const query of route.query) rows.push([`Query ${code(query.name)}`, query.description]);
      const success = `${route.response.status}: ${
        route.response.schema === undefined
          ? route.response.content === ResponseContent.Redirect
            ? 'a redirect to the return URL of the purchase'
            : 'an HTML page'
          : `${route.response.array ? 'array of ' : ''}${refLink(route.response.schema, HTTP_PAGE, pages)}`
      }`;
      rows.push(['Success', success]);
      const failures = Object.keys(asObject(operation.responses))
        .filter((status) => status !== String(route.response.status))
        .map((status) => `${status} ${HTTP_STATUS_DESCRIPTIONS[Number(status) as HttpStatus] ?? ''}`.trim());
      rows.push(['Error statuses', failures.length > 0 ? failures.join('; ') : 'none']);
      lines.push(...table(['Property', 'Value'], rows), '');
    }
  }
  lines.push(
    '## Error bodies',
    '',
    `Every error answers with ${refLink('ErrorResponse', HTTP_PAGE, pages)}: ${code('{ "error": { "code", "message", "provider?", "httpStatus?", "providerCode?", "retryable" } }')}. ` +
      'Branch on `code`. See [Errors](./errors.md) for what each code means and which HTTP status it travels with.',
    '',
  );
  return lines.join('\n');
}

const HTTP_PAGE = 'http-api.md';

function refRoute(operationId: string): string {
  return `[${operationId}](#${anchor(operationId)})`;
}

