type EnvName = (typeof EnvVar)[keyof typeof EnvVar];
const ENV_NAMES = Object.values(EnvVar) as EnvName[];

function envGroup(name: EnvName): string {
  if (name.startsWith('RAZORPAY_')) return 'Razorpay';
  if (name.startsWith('CASHFREE_')) return 'Cashfree';
  if (name.startsWith('PAYU_')) return 'PayU';
  if (name.startsWith('PHONEPE_')) return 'PhonePe';
  if (name.startsWith('PAYTM_')) return 'Paytm';
  if (name.startsWith('APP_STORE_')) return 'App Store';
  if (name.startsWith('GOOGLE_PLAY_')) return 'Google Play';
  if (name === EnvVar.PublicBaseUrl || name === EnvVar.PurchasesFile || name === EnvVar.PurchaseStoreFile) return 'Purchases';
  if (name.startsWith('SCHEDULER_')) return 'Billing scheduler';
  if (name.startsWith('EVENTS_WEBHOOK_')) return 'Events webhook';
  return 'Service';
}

const ENV_GROUPS = ['Service', 'Razorpay', 'Cashfree', 'PayU', 'PhonePe', 'Paytm', 'App Store', 'Google Play', 'Purchases', 'Billing scheduler', 'Events webhook'];

function messageOf(action: () => unknown): string | undefined {
  try {
    action();
    return undefined;
  } catch (error) {
    return error instanceof Error ? error.message : String(error);
  }
}

/** Probes the real validation: a variable is required when leaving it out makes `parseServiceEnv` say so. */
function envRequirement(name: EnvName, group: string): string {
  const full: Record<string, string> = { ...ENV_SAMPLES };
  const gatewayOf = (variable: EnvName): string => envGroup(variable);
  const base: Record<string, string> = {};
  for (const variable of ENV_NAMES) {
    const owner = gatewayOf(variable);
    if (owner === group || owner === 'Service') base[variable] = full[variable] as string;
  }
  if (group === 'Billing scheduler' || group === 'Events webhook') {
    // Needs some gateway to be valid at all.
    for (const variable of [EnvVar.RazorpayKeyId, EnvVar.RazorpayKeySecret]) base[variable] = full[variable] as string;
  }
  const without = { ...base };
  delete without[name];
  const missing = messageOf(() => parseServiceEnv(without));
  if (name === EnvVar.ApiKey) {
    return missing?.includes(`${name}: is required`) ? 'yes, unless you pass `--allow-unauthenticated`' : 'no';
  }
  if (missing?.includes(`${name}: is required`)) return 'yes';
  if (group === 'Events webhook') {
    const only = { ...without };
    const other = name === EnvVar.EventsWebhookUrl ? EnvVar.EventsWebhookSecret : EnvVar.EventsWebhookUrl;
    for (const variable of [EnvVar.EventsWebhookUrl, EnvVar.EventsWebhookSecret]) delete only[variable];
    only[other] = full[other] as string;
    if (messageOf(() => parseServiceEnv(only))?.includes(`${name}: is required when`)) return `with ${code(other)}`;
  }
  return 'no';
}

function envDefault(name: EnvName): string {
  switch (name) {
    case EnvVar.Host:
      return code(DEFAULT_HOST);
    case EnvVar.Port:
      return code(String(DEFAULT_PORT));
    case EnvVar.SchedulerTickSeconds:
      return code(String(DEFAULT_TICK_SECONDS));
    default:
      return '';
  }
}

/** The comment lines above each assignment of `.env.example`. */
function envDescriptions(): Map<string, string> {
  const lines = readFileSync(join(ROOT, '.env.example'), 'utf8').split('\n');
  const result = new Map<string, string>();
  lines.forEach((line, index) => {
    const assignment = /^([A-Z][A-Z0-9_]*)=/.exec(line);
    if (!assignment) return;
    const comment: string[] = [];
    for (let back = index - 1; back >= 0 && (lines[back] ?? '').startsWith('#'); back -= 1) {
      const text = (lines[back] ?? '').replace(/^#\s?/, '').trim();
      // `# --- Razorpay (...) ---` is a section header, not part of the variable's comment.
      if (/^-{3}/.test(text)) break;
      comment.unshift(text);
    }
    result.set(assignment[1] as string, comment.join(' ').replace(/\s+/g, ' ').trim());
  });
  return result;
}

function environmentPage(): string {
  const descriptions = envDescriptions();
  const lines = header(
    'Environment variables and command line',
    'src/service-config.ts, src/cli.ts, .env.example',
    '`india-subscriptions serve` is configured only through environment variables. A variable that is unset or blank counts as absent. ' +
      'A gateway is enabled when its required variables are all present; setting only some of them is an error, never a silently disabled gateway. ' +
      'Error messages name the variable and the rule and never contain a value.',
  );
  for (const group of ENV_GROUPS) {
    lines.push(`## ${group}`, '');
    const names = ENV_NAMES.filter((name) => envGroup(name) === group);
    lines.push(
      ...table(
        ['Variable', 'Required', 'Default', 'Description'],
        names.map((name) => [code(name), envRequirement(name, group), envDefault(name), descriptions.get(name) ?? '']),
      ),
      '',
    );
  }
  lines.push(
    '## Limits',
    '',
    `${code(EnvVar.SchedulerTickSeconds)} accepts 1 to ${MAX_TICK_SECONDS}. ${code(EnvVar.Port)} accepts 0 to 65535 (0 picks a free port).`,
    '',
    '## Command line',
    '',
    '```text',
    USAGE.trimEnd(),
    '```',
    '',
  );
  return lines.join('\n');
}


// ---------------------------------------------------------------------------
// Routing and purchases: tables read from the schemas, the constants and the policy code
// ---------------------------------------------------------------------------

/** Constant, value and meaning of one `as const` object, from its doc comments. */
function constantTable(name: string): string[] {
  const entries = CONSTANT_DOCS.get(name);
  if (!entries) throw new Error(`No constants named ${name}`);
  return table(['Constant', 'Value', 'Meaning'], entries.map((entry) => [code(`${name}.${entry.key}`), code(entry.value), entry.doc]));
}

/** Every leaf setting of the routing strategy with its default and its description, read from the Zod schema. */
function routingDefaultsTable(): string[] {
  const schema = z.toJSONSchema(RoutingStrategySchema, { io: 'input', unrepresentable: 'any' }) as Json;
  const rows: string[][] = [];
  const walk = (node: Json, path: string[]): void => {
    const properties = asObject(node.properties);
    const filled = Object.keys(asObject(node.default)).length > 0;
    if (Object.keys(properties).length > 0 && path.length > 0 && node.type === 'object' && !('additionalProperties' in node) && !filled) {
      for (const [key, value] of Object.entries(properties)) walk(asObject(value), [...path, key]);
      return;
    }
    if (path.length === 0) {
      for (const [key, value] of Object.entries(properties)) walk(asObject(value), [key]);
      return;
    }
    const fallback = node.default;
    rows.push([
      code(path.join('.')),
      fallback === undefined ? '' : code(JSON.stringify(fallback)),
      (str(node.description) ?? '').replace(/\s*Default \S+\.$/, ''),
    ]);
  };
  walk(schema, []);
  return table(['Setting', 'Default', 'Meaning'], rows);
}

/** What each platform and policy resolves to, by running the policy code on a product that has both store mappings. */
function platformPolicyTable(): string[] {
  const capabilities = [Provider.AppStore, Provider.GooglePlay, Provider.Razorpay].map((provider) => adapterCapabilities(provider));
  const product: Product = {
    key: 'pro',
    kind: ProductKind.Subscription,
    name: 'Pro',
    amount: 49900,
    interval: { unit: 'month', count: 1 },
    taxRateBps: 1800,
    appStore: { productId: 'pro' },
    googlePlay: { productId: 'pro', basePlanId: 'monthly' },
  };
  const rows: string[][] = [];
  const add = (platform: Platform, android: ChannelPolicy | undefined, goods: boolean): void => {
    const policy = PlatformPolicySchema.parse(android === undefined ? {} : { android });
    const resolved = resolvePolicy({
      platform,
      product: goods ? { ...product, physicalGoods: true, appStore: undefined, googlePlay: undefined } : product,
      policy,
      capabilities,
      hasReporter: true,
    });
    const store = resolved.store ? `${PROVIDER_LABEL[resolved.store.provider] ?? resolved.store.provider} (${code(resolved.store.provider)})` : 'none';
    const gateway =
      resolved.gateways && resolved.store ? 'only after the customer picks the alternative' : resolved.gateways ? 'the best gateway, chosen by the router' : 'never';
    rows.push([goods ? 'any platform, physical goods' : platform, goods ? 'not applicable' : code(resolved.policy), store, gateway]);
  };
  add(Platform.Ios, undefined, false);
  for (const android of Object.values(ChannelPolicy)) add(Platform.Android, android, false);
  add(Platform.Web, undefined, false);
  add(Platform.Web, undefined, true);
  return table(['Platform', 'Policy', 'Store', 'Gateway'], rows);
}

/** Which entitlement statuses give access and which block a second purchase of the same product. */
function entitlementStatusTable(): string[] {
  const docs = CONSTANT_DOCS.get('EntitlementStatus') ?? [];
  return table(
    ['Status', 'Gives access', 'Blocks a second purchase', 'Meaning'],
    docs.map((entry) => {
      const status = entry.value as PurchaseConstants.EntitlementStatus;
      return [
        code(entry.value),
        PurchaseConstants.ACCESS_STATUSES.includes(status) ? 'yes' : 'no',
        PurchaseConstants.BLOCKING_STATUSES.includes(status) ? 'yes' : 'no',
        entry.doc,
      ];
    }),
  );
}

function duration(ms: number): string {
  const units: [string, number][] = [['hour', 3_600_000], ['minute', 60_000], ['second', 1000]];
  for (const [name, size] of units) {
    if (ms % size === 0 && ms >= size) {
      const count = ms / size;
      return `${count} ${name}${count === 1 ? '' : 's'}`;
    }
  }
  return `${ms} ms`;
}

