function mapTable(map: Record<string, string>, head: [string, string]): string[] {
  return table(head, Object.entries(map).map(([from, to]) => [code(from), code(to)]));
}

function regionContent(name: string): string[] {
  const [kind, subject] = name.split(':') as [string, string | undefined];
  switch (kind) {
    case 'capabilities': {
      const provider = subject as Provider;
      return [
        ...table(['Capability', 'Value', 'Meaning'], capabilityRows(adapterCapabilities(provider))),
      ];
    }
    case 'razorpay-subscription-status':
      return mapTable(RazorpayMapper.SUBSCRIPTION_STATUS_MAP, ['Razorpay status', 'Unified status']);
    case 'razorpay-charge-status':
      return [
        ...mapTable(RazorpayMapper.INVOICE_STATUS_MAP, ['Razorpay invoice status', 'Unified charge status']),
        '',
        ...mapTable(RazorpayMapper.PAYMENT_STATUS_MAP, ['Razorpay payment status', 'Unified charge status']),
      ];
    case 'razorpay-refund-status':
      return mapTable(RazorpayMapper.REFUND_STATUS_MAP, ['Razorpay refund status', 'Unified refund status']);
    case 'razorpay-webhook-events':
      return mapTable(RazorpayMapper.WEBHOOK_EVENT_MAP, ['Razorpay event', 'Unified event']);
    case 'cashfree-subscription-status':
      return mapTable(CashfreeConstants.SUBSCRIPTION_STATUS_MAP, ['Cashfree subscription status', 'Unified status']);
    case 'cashfree-charge-status':
      return [
        ...mapTable(CashfreeConstants.PAYMENT_STATUS_MAP, ['Cashfree payment status', 'Unified charge status']),
        '',
        ...mapTable(CashfreeConstants.PAYMENT_TYPE_MAP, ['Cashfree payment type', 'Unified charge kind']),
      ];
    case 'cashfree-refund-status':
      return mapTable(CashfreeConstants.REFUND_STATUS_MAP, ['Cashfree refund status', 'Unified refund status']);
    case 'cashfree-webhook-events':
      return mapTable(CashfreeConstants.STATUS_EVENT_MAP, ['Status in `SUBSCRIPTION_STATUS_CHANGED`', 'Unified event']);
    case 'payu-subscription-status':
      return [
        ...mapTable(PayUConstants.CARD_MANDATE_STATUS, ['Card mandate status (`check_mandate_status`)', 'Unified status']),
        '',
        ...mapTable(PayUConstants.ENACH_MANDATE_STATUS, ['eNACH mandate status (`NB_mandate_status`)', 'Unified status']),
        '',
        ...mapTable(PayUConstants.UPI_MANDATE_STATUS, ['UPI mandate status (`upi_mandate_status`)', 'Unified status']),
      ];
    case 'payu-charge-status':
      return mapTable(PayUConstants.CHARGE_STATUS_BY_STATE, ['PayU transaction state', 'Unified charge status']);
    case 'payu-webhook-events':
      return [
        ...mapTable(PayUConstants.EVENT_BY_MANDATE_NOTIFICATION, ['Card mandate `notificationType`', 'Unified event']),
        '',
        ...mapTable(PayUConstants.EVENT_BY_UPI_ACTION, ['UPI mandate `action`', 'Unified event']),
      ];
    case 'phonepe-subscription-status':
      return [
        ...mapTable(PhonePeConstants.SUBSCRIPTION_STATE_TO_STATUS, ['PhonePe mandate state', 'Unified status']),
        '',
        ...mapTable(
          PhonePeConstants.SETUP_ORDER_STATE_TO_STATUS as Record<string, string>,
          ['Setup order state (before the mandate exists)', 'Unified status'],
        ),
      ];
    case 'phonepe-charge-status':
      return mapTable(PhonePeConstants.ORDER_STATE_TO_CHARGE_STATUS, ['PhonePe order state', 'Unified charge status']);
    case 'phonepe-refund-status':
      return mapTable(PhonePeConstants.REFUND_STATE_TO_STATUS, ['PhonePe refund state', 'Unified refund status']);
    case 'phonepe-frequencies':
      return table(
        ['Plan interval', 'PhonePe frequency'],
        PhonePeConstants.FREQUENCY_BY_INTERVAL.map((entry) => [`${entry.count} ${entry.unit}`, code(entry.frequency)]),
      );
    case 'paytm-subscription-status':
      return mapTable(PaytmConstants.SUBSCRIPTION_STATUS_MAP, ['Paytm subscription status', 'Unified status']);
    case 'paytm-charge-status':
      return mapTable(PaytmConstants.PAYTM_CHARGE_STATUS_MAP, ['Paytm transaction status', 'Unified charge status']);
    case 'paytm-payment-modes':
      return mapTable(PaytmConstants.PAYMENT_MODE_MAP, ['Paytm payment mode', 'Unified payment method']);
    case 'paytm-webhook-events':
      return [
        ...mapTable(PaytmConstants.SUBSCRIPTION_EVENT_MAP, ['Status in the subscription status webhook', 'Unified event']),
        '',
        ...mapTable(PaytmConstants.PAYMENT_EVENT_MAP, ['Status in the payment webhook', 'Unified event']),
      ];
    case 'paytm-frequencies':
      return table(
        ['Plan interval', 'Paytm frequency unit'],
        PaytmConstants.PAYTM_FREQUENCY_FOR_INTERVAL.map((entry) => [`${entry.count} ${entry.unit}`, code(entry.frequency)]),
      );
    case 'appstore-subscription-status':
      return [
        ...table(
          ['App Store status', 'Unified status'],
          Object.entries(AppStoreConstants.AppStoreSubscriptionStatus).map(([name, number]) => [
            `${code(String(number))} ${name}`,
            code(AppStoreConstants.SUBSCRIPTION_STATUS_MAP[number]),
          ]),
        ),
        '',
        ...table(
          ['Expiration intent of an expired subscription', 'Unified status'],
          Object.entries(AppStoreConstants.ExpirationIntent).map(([name, number]) => [
            `${code(String(number))} ${name}`,
            code(AppStoreConstants.EXPIRATION_INTENT_STATUS[number]),
          ]),
        ),
        '',
        `A status Apple adds later is \`${AppStoreConstants.UNKNOWN_SUBSCRIPTION_STATUS}\`.`,
      ];
    case 'appstore-revocation-status':
      return table(
        ['Revocation type of a transaction', 'Unified payment status', 'Unified charge status'],
        Object.entries(AppStoreConstants.REVOCATION_PAYMENT_STATUS).map(([type, status]) => [
          code(type),
          code(status),
          code(AppStoreConstants.REVOCATION_CHARGE_STATUS[type] ?? ''),
        ]),
      );
    case 'appstore-webhook-events':
      return table(
        ['Notification type (and subtype)', 'Unified event'],
        Object.entries(AppStoreConstants.NOTIFICATION_EVENT_MAP).map(([key, event]) => [code(key), code(event)]),
      );
    case 'googleplay-subscription-status':
      return [
        ...mapTable(GooglePlayConstants.SUBSCRIPTION_STATUS_BY_STATE, ['Google subscription state', 'Unified status']),
        '',
        `A state Google adds later is \`${GooglePlayConstants.SUBSCRIPTION_STATUS_FALLBACK}\`.`,
      ];
    case 'googleplay-payment-status':
      return [
        ...mapTable(GooglePlayConstants.PAYMENT_STATUS_BY_PURCHASE_STATE, ['Google one-time purchase state', 'Unified payment status']),
        '',
        `A state Google adds later is \`${GooglePlayConstants.PAYMENT_STATUS_FALLBACK}\`.`,
      ];
    case 'googleplay-webhook-events':
      return [
        ...table(
          ['Subscription notification', 'Unified event'],
          Object.entries(GooglePlayConstants.SUBSCRIPTION_EVENT_BY_NOTIFICATION).map(([type, event]) => [
            `${code(GooglePlayConstants.SUBSCRIPTION_NOTIFICATION_NAMES[Number(type) as GooglePlayConstants.SubscriptionNotificationType])} (${type})`,
            code(event),
          ]),
        ),
        '',
        ...table(
          ['One-time product notification', 'Unified event'],
          Object.entries(GooglePlayConstants.ONE_TIME_EVENT_BY_NOTIFICATION).map(([type, event]) => [
            `${code(GooglePlayConstants.ONE_TIME_NOTIFICATION_NAMES[Number(type) as GooglePlayConstants.OneTimeNotificationType])} (${type})`,
            code(event),
          ]),
        ),
      ];
    case 'one-time-methods':
      return table(
        ['Provider', 'One-time payments', 'Methods of a one-time payment', 'Methods of a mandate'],
        PROVIDERS.map((provider) => {
          const shown = adapterCapabilities(provider);
          return [
            PROVIDER_LABEL[provider] ?? provider,
            formatCapability(shown.oneTimePayments),
            shown.oneTimePaymentMethods.length > 0 ? formatCapability(shown.oneTimePaymentMethods) : 'none to choose',
            shown.paymentMethods.length > 0 ? formatCapability(shown.paymentMethods) : 'none to choose',
          ];
        }),
      );
    case 'payment-statuses':
      return constantTable('PaymentStatus');
    case 'routing-defaults':
      return routingDefaultsTable();
    case 'route-exclusions':
      return constantTable('RouteExclusion');
    case 'platform-policy':
      return platformPolicyTable();
    case 'entitlement-statuses':
      return entitlementStatusTable();
    default:
      throw new Error(`Unknown generated region "${name}"`);
  }
}

/** Rewrites every generated region of a hand-written page. Returns undefined when the page has none. */
function fillRegions(source: string): string | undefined {
  const lines = source.split('\n');
  const output: string[] = [];
  let found = false;
  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i] as string;
    const begin = BEGIN.exec(line);
    if (!begin) {
      output.push(line);
      continue;
    }
    found = true;
    let close = i + 1;
    while (close < lines.length && lines[close] !== END) close += 1;
    if (close >= lines.length) throw new Error(`Region "${begin[1]}" has no ${END}`);
    output.push(line, '', ...regionContent(begin[1] as string), '', END);
    i = close;
  }
  return found ? output.join('\n') : undefined;
}

// ---------------------------------------------------------------------------
// Entry points
// ---------------------------------------------------------------------------

/** Every generated file, as `path relative to docs/` -> content. Does not touch the disk except to read sources. */
export function generateAll(): Map<string, string> {
  const { pages, models, scheduler } = buildPages();
  const files = new Map<string, string>();
  const put = (name: string, content: string): void => {
    files.set(`${GENERATED_DIR}/${name}`, `${content.trimEnd()}\n`);
  };
  put(MODELS_PAGE, modelsPage(models, pages));
  put(ENUMS_PAGE, enumsPage(models, scheduler));
  put(SCHEDULER_PAGE, schedulerPage(scheduler, pages));
  put(HTTP_PAGE, httpApiPage(pages));
  put('errors.md', errorsPage());
  put('capabilities.md', capabilitiesPage());
  put('environment.md', environmentPage());
  put(ROUTING_PAGE, routingPage(pages));
  put(PURCHASES_PAGE, purchasesPage(pages));

  for (const provider of PROVIDERS) {
    const path = `gateways/${gatewayPageFile(provider)}`;
    const current = readFileSync(join(DOCS, path), 'utf8');
    const filled = fillRegions(current);
    if (filled !== undefined) files.set(path, filled.endsWith('\n') ? filled : `${filled}\n`);
  }
  for (const path of REGION_PAGES) {
    if (!existsSync(join(DOCS, path))) continue;
    const filled = fillRegions(readFileSync(join(DOCS, path), 'utf8'));
    if (filled !== undefined) files.set(path, filled.endsWith('\n') ? filled : `${filled}\n`);
  }
  return files;
}

/** Hand-written pages outside docs/gateways/ that also carry generated regions. */
export const REGION_PAGES = ['guides/one-time-payments.md', 'guides/purchases.md', 'guides/routing.md', 'concepts/entitlements.md'];

export const GENERATED_PATHS = ['models', 'enums', 'scheduler-records', 'http-api', 'errors', 'capabilities', 'environment', 'routing', 'purchases'].map(
  (name) => `${GENERATED_DIR}/${name}.md`,
);

function main(): void {
  const files = generateAll();
  for (const [path, content] of files) {
    const target = join(DOCS, path);
    mkdirSync(dirname(target), { recursive: true });
    writeFileSync(target, content);
  }
  console.log(`wrote ${files.size} files under docs/ (${[...files.keys()].join(', ')})`);
}

if (process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main();
}
